  static ResponsePlaybook localize(ResponsePlaybook item, String code) {
    if (code != 'ar') return item;
    final value = _data[item.id];
    if (value == null) return item;
    return ResponsePlaybook(
      id: item.id,
      title: value['title']! as String,
      scenario: item.scenario,
      summary: value['summary']! as String,
      firstAction: value['firstAction']! as String,
      steps: List<String>.unmodifiable(value['steps']! as List<String>),
      preserve: List<String>.unmodifiable(value['preserve']! as List<String>),
      avoid: List<String>.unmodifiable(value['avoid']! as List<String>),
      limit: value['limit']! as String,
    );
